-- 电商兑换漏斗汇总：供 Pipe 兑换漏斗报表使用
-- 按兑换漏斗唯一键及唯一统计行收敛；只汇总数值指标，不在 Change 侧计算率
set spark.driver.memory=8g;
set spark.driver.cores=1;
set spark.executor.memory=8g;
set spark.executor.cores=2;
set spark.sql.shuffle.partitions=400;

WITH redeem_key_level AS (
    SELECT
        redeem_funnel_order_key,
        MAX(redeem_funnel_pay_dt) AS pay_dt,
        COALESCE(
            MAX(CASE
                  WHEN TRIM(COALESCE(daren_name, '')) NOT IN ('', '未知达人', '@pipe_null@')
                  THEN TRIM(daren_name)
                END),
            '未配置'
        ) AS daren_name,
        COALESCE(MAX(out_item_id), '未配置') AS goodsid,
        COALESCE(MAX(CASE WHEN TRIM(COALESCE(subject_name, '')) NOT IN ('', '@pipe_null@') THEN TRIM(subject_name) END), '未配置') AS subject_name,
        COALESCE(MAX(city_type), '未配置') AS user_city_type,
        COALESCE(MAX(account_id), 'unset') AS accountid,
        COALESCE(MAX(ad_channel), '未配置') AS ad_channel,
        COALESCE(MAX(third_channel), '未配置') AS third_channel,
        COALESCE(MAX(zj_type), '未配置') AS zj_type,
        COALESCE(MAX(zj_level), '未配置') AS zj_level,
        MAX(redeem_funnel_stage) AS redeem_funnel_stage,
        MAX(redeem_funnel_node) AS redeem_funnel_node,
        MAX(redeem_final_status) AS redeem_final_status,
        MAX(CAST(COALESCE(is_valid_redeem_order, '0') AS INT)) AS is_valid_redeem_order,
        MAX(COALESCE(CAST(has_jingyu_auth_callback AS INT), 0)) AS has_jingyu_auth_callback
    FROM dw_conan_ads.ads_commerce_try_order_detail_wide_da_v1
    WHERE dt = '${date}'
      AND CAST(is_redeem_funnel_order AS INT) = 1
      AND CAST(is_redeem_funnel_metric_row AS INT) = 1
      AND redeem_funnel_order_key IS NOT NULL
      AND redeem_funnel_pay_dt BETWEEN DATE_ADD(CAST('${date}' AS DATE), -31) AND CAST('${date}' AS DATE)
    GROUP BY redeem_funnel_order_key
),
goods_map AS (
    SELECT
        CAST(goodsid AS STRING) AS goodsid,
        MAX(dianpu) AS dianpu,
        MAX(type) AS type,
        MAX(sku) AS sku
    FROM dw_conan_temp.goods_detail_v2
    GROUP BY CAST(goodsid AS STRING)
),
base AS (
    SELECT
        r.pay_dt,
        COALESCE(g.dianpu, '未配置') AS dianpu,
        COALESCE(g.type, '未配置') AS type,
        r.daren_name AS zhibojian,
        r.goodsid,
        r.subject_name,
        COALESCE(g.sku, '未配置') AS sku,
        r.user_city_type,
        r.accountid,
        r.ad_channel,
        r.third_channel,
        r.zj_type,
        r.zj_level,
        CAST(CAST(date_trunc('WEEK', CAST(r.pay_dt AS TIMESTAMP)) AS DATE) AS STRING) AS week_dt,
        r.redeem_funnel_stage,
        r.redeem_funnel_node,
        r.redeem_final_status,
        r.is_valid_redeem_order,
        CASE
            WHEN r.redeem_funnel_node IN ('主动兑换成功', '主动兑换撞库', '主动兑换后退款')
                THEN CASE WHEN r.has_jingyu_auth_callback = 1 THEN '小程序主动兑换'
                          ELSE '斑马主动兑换' END
            WHEN r.redeem_funnel_stage = '主动兑换' AND r.redeem_funnel_node = '未兑换退款'
                THEN '未兑换退款'
            WHEN r.redeem_funnel_stage = '主动兑换' AND r.redeem_funnel_node = '主动兑换失败'
                THEN '主动兑换失败'
            WHEN r.redeem_funnel_stage = '被动兑换' THEN '被动兑换'
            WHEN r.redeem_funnel_stage = '待兑换' THEN '待兑换'
            ELSE '其他'
        END AS redeem_entry_type
    FROM redeem_key_level r
    LEFT JOIN goods_map g
      ON CAST(r.goodsid AS STRING) = g.goodsid
)
SELECT
    '${date}' AS dt,
    p.*,
    CURRENT_TIMESTAMP() AS dbctime,
    CURRENT_TIMESTAMP() AS dbutime
FROM (
    SELECT
        week_dt AS pay_dt,
        COALESCE(dianpu, 'total_count') AS dianpu,
        COALESCE(type, 'total_count') AS type,
        COALESCE(zhibojian, 'total_count') AS zhibojian,
        COALESCE(goodsid, 'total_count') AS goodsid,
        COALESCE(sku, 'total_count') AS sku,
        COALESCE(user_city_type, 'total_count') AS user_city_type,
        COALESCE(accountid, 'total_count') AS accountid,
        COALESCE(ad_channel, 'total_count') AS ad_channel,
        COALESCE(third_channel, 'total_count') AS third_channel,
        COALESCE(zj_type, 'total_count') AS zj_type,
        COALESCE(zj_level, 'total_count') AS zj_level,
        COALESCE(subject_name, 'total_count') AS subject_name,
        '周' AS week_range,
        SUM(1) AS redeem_chain_order_num,
        SUM(CASE WHEN is_valid_redeem_order = 1 THEN 1 ELSE 0 END) AS redeem_success_order_num,
        SUM(CASE WHEN redeem_final_status = '撞库' THEN 1 ELSE 0 END) AS redeem_collision_order_num,
        SUM(CASE WHEN redeem_final_status = '退款' THEN 1 ELSE 0 END) AS redeem_refund_order_num,
        SUM(CASE WHEN redeem_funnel_node = '主动兑换成功' THEN 1 ELSE 0 END) AS active_redeem_success_order_num,
        SUM(CASE WHEN redeem_funnel_node = '主动兑换撞库' THEN 1 ELSE 0 END) AS active_redeem_collision_order_num,
        SUM(CASE WHEN redeem_funnel_node = '主动兑换后退款' THEN 1 ELSE 0 END) AS active_redeem_refund_order_num,
        SUM(CASE WHEN redeem_funnel_node = '主动兑换失败' THEN 1 ELSE 0 END) AS active_redeem_failure_order_num,
        SUM(CASE WHEN redeem_funnel_stage = '待兑换' THEN 1 ELSE 0 END) AS active_redeem_pending_order_num,
        SUM(CASE WHEN redeem_funnel_stage = '被动兑换' THEN 1 ELSE 0 END) AS passive_redeem_enter_order_num,
        SUM(CASE WHEN redeem_funnel_node = '被动兑换成功' THEN 1 ELSE 0 END) AS passive_redeem_success_order_num,
        SUM(CASE WHEN redeem_funnel_node = '被动兑换撞库' THEN 1 ELSE 0 END) AS passive_redeem_collision_order_num,
        SUM(CASE WHEN redeem_funnel_node = '被动兑换退款' THEN 1 ELSE 0 END) AS passive_redeem_refund_order_num,
        SUM(CASE WHEN redeem_funnel_node = '解密失败' THEN 1 ELSE 0 END) AS passive_redeem_failure_order_num,
        COALESCE(redeem_entry_type, 'total_count') AS redeem_entry_type
    FROM base
    GROUP BY GROUPING SETS (
        (week_dt),
        (week_dt, dianpu),
        (week_dt, type),
        (week_dt, dianpu, type),
