    SELECT
        pay_dt,
        COALESCE(dianpu, 'total_count') AS dianpu,
        COALESCE(type, 'total_count') AS type,
        COALESCE(zhibojian, 'total_count') AS zhibojian,
        COALESCE(goodsid, 'total_count') AS goodsid,
        COALESCE(sku, 'total_count') AS sku,
        COALESCE(user_city_type, 'total_count') AS user_city_type,
        COALESCE(accountid, 'total_count') AS accountid,
        COALESCE(ad_channel, 'total_count') AS ad_channel,
        COALESCE(third_channel, 'total_count') AS third_channel,
        COALESCE(zj_type, 'total_count') AS zj_type,
        COALESCE(zj_level, 'total_count') AS zj_level,
        COALESCE(subject_name, 'total_count') AS subject_name,
        '日' AS week_range,
        SUM(1) AS redeem_chain_order_num,
        SUM(CASE WHEN is_valid_redeem_order = 1 THEN 1 ELSE 0 END) AS redeem_success_order_num,
        SUM(CASE WHEN redeem_final_status = '撞库' THEN 1 ELSE 0 END) AS redeem_collision_order_num,
        SUM(CASE WHEN redeem_final_status = '退款' THEN 1 ELSE 0 END) AS redeem_refund_order_num,
        SUM(CASE WHEN redeem_funnel_node = '主动兑换成功' THEN 1 ELSE 0 END) AS active_redeem_success_order_num,
        SUM(CASE WHEN redeem_funnel_node = '主动兑换撞库' THEN 1 ELSE 0 END) AS active_redeem_collision_order_num,
        SUM(CASE WHEN redeem_funnel_node = '主动兑换后退款' THEN 1 ELSE 0 END) AS active_redeem_refund_order_num,
        SUM(CASE WHEN redeem_funnel_node = '主动兑换失败' THEN 1 ELSE 0 END) AS active_redeem_failure_order_num,
        SUM(CASE WHEN redeem_funnel_stage = '待兑换' THEN 1 ELSE 0 END) AS active_redeem_pending_order_num,
        SUM(CASE WHEN redeem_funnel_stage = '被动兑换' THEN 1 ELSE 0 END) AS passive_redeem_enter_order_num,
        SUM(CASE WHEN redeem_funnel_node = '被动兑换成功' THEN 1 ELSE 0 END) AS passive_redeem_success_order_num,
        SUM(CASE WHEN redeem_funnel_node = '被动兑换撞库' THEN 1 ELSE 0 END) AS passive_redeem_collision_order_num,
        SUM(CASE WHEN redeem_funnel_node = '被动兑换退款' THEN 1 ELSE 0 END) AS passive_redeem_refund_order_num,
        SUM(CASE WHEN redeem_funnel_node = '解密失败' THEN 1 ELSE 0 END) AS passive_redeem_failure_order_num,
        COALESCE(redeem_entry_type, 'total_count') AS redeem_entry_type
    FROM base
